'use strict';
// Draft generated by FreeLLMAPI (gpt-oss-20b via ovh); saved by Claude.
const asyncHandler = require('../utils/asyncHandler');
const ok = (res, data, status) => res.status(status || 200).json({ success: true, data });

const { userIdParams, requesterParams, followerParams, respondBody, pageQuery, usernameParams } = require('../validators/followValidators');
const {
  followUser,
  unfollowUser,
  listIncomingRequests,
  respondToRequest,
  listFollowers,
  listFollowing,
  removeFollower,
} = require('../services/followService');

exports.follow = asyncHandler(async (req, res) => {
  const { userId } = userIdParams.parse(req.params);
  const followerId = req.user.id;
  const result = await followUser(followerId, userId);
  ok(res, result);
});

exports.unfollow = asyncHandler(async (req, res) => {
  const { userId } = userIdParams.parse(req.params);
  const followerId = req.user.id;
  const result = await unfollowUser(followerId, userId);
  ok(res, result);
});

exports.incomingRequests = asyncHandler(async (req, res) => {
  const { limit, cursor } = pageQuery.parse(req.query);
  const result = await listIncomingRequests(req.user.id, limit, cursor);
  ok(res, result);
});

exports.respond = asyncHandler(async (req, res) => {
  const { requesterId } = requesterParams.parse(req.params);
  const { action } = respondBody.parse(req.body);
  const result = await respondToRequest(req.user.id, requesterId, action);
  ok(res, result);
});

exports.followers = asyncHandler(async (req, res) => {
  const { username } = usernameParams.parse(req.params);
  const { limit, cursor } = pageQuery.parse(req.query);
  const viewerId = req.user ? req.user.id : null;
  const result = await listFollowers(viewerId, username, limit, cursor);
  ok(res, result);
});

exports.following = asyncHandler(async (req, res) => {
  const { username } = usernameParams.parse(req.params);
  const { limit, cursor } = pageQuery.parse(req.query);
  const viewerId = req.user ? req.user.id : null;
  const result = await listFollowing(viewerId, username, limit, cursor);
  ok(res, result);
});

exports.removeFollower = asyncHandler(async (req, res) => {
  const { followerId } = followerParams.parse(req.params);
  const result = await removeFollower(req.user.id, followerId);
  ok(res, result);
});
